// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, bool heavy) public {
        amount = bound(amount, 1, 1 ether);

        PayableHelper helper = new PayableHelper(heavy);

        vm.deal(address(this), amount);

        bool ok;
        (bool s,) = address(c).call{value: amount}("");
        require(s);

        try c.sendMoney(address(helper), amount, "") {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

contract PayableHelper {
    bool public heavy;
    constructor(bool _heavy) payable { heavy = _heavy; }
    receive() external payable {
        if (heavy) {
            for (uint i = 0; i < 200; i++) {
                bytes32 slot = keccak256(abi.encodePacked(i));
                assembly { sstore(slot, 1) }
            }
        }
    }
}
